#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto doOp = [&](int x, int y){
        assert(x>0 && y>0 && x+y<n);
        ops.push_back({x,y});
        vector<int> np;
        // [suffix y | middle | prefix x]
        // suffix: p[n-y .. n-1]
        // middle: p[x .. n-y-1]
        // prefix: p[0 .. x-1]
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p = np;
    };

    for(int placed=0; placed<n-1; placed++){
        int pos = -1;
        for(int i=placed;i<n;i++) if(p[i]==placed+1){pos=i;break;}
        if(pos==placed) continue;

        // Element placed+1 is at position pos, needs to go to position placed
        // Strategy: use one op to bring it to a good spot, then another to place it

        int remaining = n; // we work on full array but elements [0..placed-1] are already correct

        if(pos == n-1 && placed == 0){
            // suffix y=1, prefix x: need x+1<n, just pick x=1 if n>2
            // Result: [p[n-1]] + [p[1..n-2]] + [p[0]] -> element at pos 0
            doOp(1, 1);
            // Recheck
            continue;
        }

        // Step 1: Move element to position n-1 if not already there
        if(pos < n-1){
            // x = pos+1, y = n-1-pos. x+y = n. Need x+y < n.
            // So use: x = pos-placed, offset from placed. Actually let me use:
            // prefix = pos+1, suffix = n-1-pos... sum = n, too big.
            // Use x=1, y=n-1-pos if 1+n-1-pos < n => pos > 0. 
            // After op: [p[pos+1..n-1]] + [p[1..pos]] + [p[0]]
            // element was at pos, now at pos (in p[1..pos] block starting at index n-1-pos)
            // New index: (n-1-pos) + (pos-1) = n-2. Great, it's at n-2... no.
            // Let me just: x=pos-placed+1 (>0 since pos>placed), y=n-1-pos (could be 0)
            // If pos==n-1, skip. Else y=n-1-pos>0, x=pos-placed+1, x+y=n-placed, need <n => placed>0
            if(placed > 0 && pos < n-1){
                doOp(placed, n-1-pos);
                pos = n-1-(pos-placed); // element moves
                for(int i=0;i<n;i++) if(p[i]==placed+1){pos=i;break;}
            } else if(placed==0 && pos<n-1){
                doOp(pos, n-1-pos);
                for(int i=0;i<n;i++) if(p[i]==placed+1){pos=i;break;}
            }
        }
        if(pos==placed) continue;
        // Now place it: element at pos, want at placed
        // x=placed+1, y=n-pos if valid? x+y=placed+1+n-pos, need<n => placed+1<pos => placed<pos (true)
        if(placed+1>0 && n-pos>0 && placed+1+n-pos<n && pos>placed){
            doOp(placed+1, n-pos);
            for(int i=0;i<n;i++) if(p[i]==placed+1){pos=i;break;}
        } else if(pos!=placed){
            // fallback
            if(pos>0 && pos<n-1){
                doOp(1, n-pos);
                for(int i=0;i<n;i++) if(p[i]==placed+1){pos=i;break;}
            }
            if(pos!=placed && placed+1+n-pos<n && n-pos>0 && placed+1>0){
                doOp(placed+1, n-pos);
            }
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
